// XdgPopup: short-lived, popup surfaces for menus
type XdgPopup struct {
	Proxy
	events *XdgPopupEvents
}

// XdgPopupInterface describes xdg_popup, up to version 7.
var XdgPopupInterface = newInterface("xdg_popup", 7)

func init() {
	XdgPopupInterface.setMessages(
		[]message{
			{"destroy", "", []*Interface{}},
			{"grab", "ou", []*Interface{WlSeatInterface, nil}},
			{"reposition", "3ou", []*Interface{XdgPositionerInterface, nil}},
		},
		[]message{
			{"configure", "iiii", []*Interface{nil, nil, nil, nil}},
			{"popup_done", "", []*Interface{}},
			{"repositioned", "3u", []*Interface{nil}},
		},
	)
}

func newXdgPopup(c *Conn, proxy uintptr) *XdgPopup {
	self := new(XdgPopup)
	c.register(self, proxy, true)
	return self
}

// Ptr returns the wl_proxy pointer, or 0 for a nil XdgPopup.
func (self *XdgPopup) Ptr() uintptr {
	if self == nil {
		return 0
	}
	return self.ptr
}

// BindXdgPopup binds the global xdg_popup with the given registry name and version.
func BindXdgPopup(registry *WlRegistry, name, version uint32) *XdgPopup {
	proxy := registry.BindRaw(name, XdgPopupInterface, version)
	if proxy == 0 {
		return nil
	}
	return newXdgPopup(registry.conn, proxy)
}

// XdgPopupError:
type XdgPopupError uint32

const (
	// XdgPopupErrorInvalidGrab: tried to grab after being mapped
	XdgPopupErrorInvalidGrab XdgPopupError = 0
)

// XdgPopupEvents holds the callbacks for the events of xdg_popup. A nil callback ignores the event.
type XdgPopupEvents struct {
	// OnConfigure: configure the popup surface
	OnConfigure func(x int32, y int32, width int32, height int32)
	// OnPopupDone: popup interaction is done
	OnPopupDone func()
	// OnRepositioned: signal the completion of a repositioned request
	OnRepositioned func(token uint32)
}

// SetEvents sets the callbacks for the events of the object. It replaces the previous ones.
func (self *XdgPopup) SetEvents(events *XdgPopupEvents) { self.events = events }

func (self *XdgPopup) dispatch(opcode uint32, a eventArgs) {
	ev := self.events
	switch opcode {
	case 0: // configure
		if ev == nil || ev.OnConfigure == nil {
			return
		}
		ev.OnConfigure(a.int(0), a.int(1), a.int(2), a.int(3))
	case 1: // popup_done
		if ev == nil || ev.OnPopupDone == nil {
			return
		}
		ev.OnPopupDone()
	case 2: // repositioned
		if ev == nil || ev.OnRepositioned == nil {
			return
		}
		ev.OnRepositioned(a.uint(0))
	}
}

// Destroy: remove xdg_popup interface. It destroys the object.
func (self *XdgPopup) Destroy() {
	argv := newArgs(0)
	defer argv.free()
	self.marshal(0, nil, self.version, flagDestroy, argv)
}

// Grab: make the popup take an explicit grab.
func (self *XdgPopup) Grab(seat *WlSeat, serial uint32) {
	argv := newArgs(2)
	defer argv.free()
	argv.setObject(0, seat.Ptr())
	argv.setUint(1, serial)
	self.marshal(1, nil, self.version, 0, argv)
}

// Reposition: recalculate the popup's location. Since version 3.
func (self *XdgPopup) Reposition(positioner *XdgPositioner, token uint32) {
	argv := newArgs(2)
	defer argv.free()
	argv.setObject(0, positioner.Ptr())
	argv.setUint(1, token)
	self.marshal(2, nil, self.version, 0, argv)
}
